package com.lore.zzal.generation.client;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import java.net.http.HttpClient;import java.util.*;
class OpenAiImageUsageRecorderTest {
 @Test void storageFailureAfter200KeepsUsage()throws Exception{try(var stub=new UsageStub()){var storage=mock(com.lore.common.s3.S3Storage.class);doThrow(new IllegalStateException("synthetic disk failure")).when(storage).upload(anyString(),any(),anyString());var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiImageClient(storage,"SECRET_KEY",2,HttpClient.newHttpClient(),stub.endpoint(),events::add);assertThatThrownBy(()->c.generate("SECRET_PROMPT",List.of(),"images/test.png",new ModelSpec("gpt-image-2","1248x1248","medium"))).isInstanceOf(BilledFailureException.class);assertThat(events).hasSize(1);assertThat(events.getLast().usageRaw().path("prompt_tokens").asInt()).isEqualTo(100);assertThat(events.getLast().xRequestId()).isEqualTo("req-test-1");assertThat(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(events)).doesNotContain("SECRET","b64_json");assertThat(stub.requests.get()).isEqualTo(1);}}
 @Test void malformed200StillRecordsHeader()throws Exception{try(var stub=new UsageStub()){stub.body="invalid";var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiImageClient(null,"TEST",2,HttpClient.newHttpClient(),stub.endpoint(),events::add);assertThatThrownBy(()->c.generate("p",List.of(),"images/test",ModelSpec.of("gpt-image-2"))).isInstanceOf(Exception.class);assertThat(events).hasSize(1);assertThat(events.getFirst().outcome()).isEqualTo(ProviderUsageRecorder.Outcome.UNKNOWN);assertThat(events.getFirst().xRequestId()).isEqualTo("req-test-1");}}
 @Test void recorderFailureDoesNotPreventStorage()throws Exception{try(var stub=new UsageStub()){var storage=mock(com.lore.common.s3.S3Storage.class);var c=new OpenAiImageClient(storage,"TEST",2,HttpClient.newHttpClient(),stub.endpoint(),e->{throw new java.io.IOException("record failed");});assertThatCode(()->c.generate("p",List.of(),"images/test",ModelSpec.of("gpt-image-2"))).doesNotThrowAnyException();verify(storage).upload(eq("images/test"),any(),eq("image/png"));assertThat(stub.requests.get()).isEqualTo(1);}}
}
